{
  "id": "genetics-laws-highschool",
  "title": "遗传学定律",
  "subtitle": "从孟德尔豌豆实验到现代遗传学",
  "language": "zh-CN",
  "audience": "高中生物学",
  "theme": "cobalt-grid",
  "tutor": {
    "suggestions": [
      "为什么孟德尔选择豌豆作为实验材料？他的实验设计有什么巧妙之处？",
      "如何区分显性性状和隐性性状？杂合子为什么表现显性性状？",
      "分离定律和自由组合定律的区别是什么？它们在减数分裂中如何体现？",
      "如果两对基因位于同一对染色体上，还会自由组合吗？这说明了什么？"
    ],
    "kb": [
      {
        "pattern": "分离定律|孟德尔第一定律",
        "answer": "在形成配子时，成对的遗传因子彼此分离，分别进入不同的配子中。配子只含每对因子中的一个。"
      },
      {
        "pattern": "自由组合定律|孟德尔第二定律",
        "answer": "不同对的遗传因子在形成配子时自由组合，互不干扰。位于非同源染色体上的基因独立分配。"
      },
      {
        "pattern": "显性性状|隐性性状",
        "answer": "在杂合子中表现出来的性状为显性性状，未表现的为隐性性状。显性并非更常见或更‘强’。"
      },
      {
        "pattern": "纯合子|杂合子",
        "answer": "成对遗传因子相同的个体为纯合子（如 DD 或 dd），不同的为杂合子（如 Dd）。杂合子表现显性性状。"
      },
      {
        "pattern": "测交|回交",
        "answer": "与隐性纯合子杂交，用于验证某个个体的基因型。若后代出现隐性性状，则亲本为杂合子。"
      },
      {
        "pattern": "连锁交换|摩尔根",
        "answer": "位于同一染色体上的基因倾向于一起遗传（连锁），但减数分裂时同源染色体交换片段可导致基因重组（交换）。"
      }
    ]
  },
  "scenes": [
    {
      "id": "cover",
      "kind": "hero",
      "notes": "本课将带领学生从孟德尔的经典实验出发，理解遗传学两大定律，并探讨现代遗传学对定律的扩展。重点培养科学思维和解题能力。",
      "blocks": [
        {
          "id": "b_cover",
          "type": "hero",
          "intent": "封面：标题‘遗传学定律’，副题‘从豌豆实验到基因的奥秘’"
        }
      ]
    },
    {
      "id": "mendel-experiment",
      "kind": "content",
      "eyebrow": "引言",
      "headline": "种瓜得瓜，种豆得豆：遗传现象的探索",
      "lead": "孟德尔通过豌豆杂交实验，首次揭示了遗传的基本规律。",
      "notes": "从生活经验出发，引出遗传现象的普遍性。介绍孟德尔选择豌豆的原因：自花传粉、闭花授粉，相对性状明显（如高茎与矮茎），易于人工杂交。强调他的实验设计：去雄、人工授粉、统计分析，这是假说-演绎法的典范。同时提及当时科学界对融合遗传的误解，为后续假说做铺垫。",
      "blocks": [
        {
          "id": "b2",
          "type": "agenda",
          "intent": "列举孟德尔选择豌豆的四大优点及实验设计的关键步骤（去雄、授粉、套袋）"
        }
      ]
    },
    {
      "id": "segregation-law",
      "kind": "content",
      "eyebrow": "分离定律",
      "headline": "成对因子，分离到配子",
      "lead": "一对相对性状的杂交实验揭示了分离定律。",
      "notes": "详细讲解高茎（DD）与矮茎（dd）杂交：P→F1 全为高茎（Dd），F1 自交→F2 高:矮=3:1。孟德尔提出假说：①遗传因子成对存在；②形成配子时因子分离；③受精时雌雄配子随机结合。用棋盘法展示 F2 基因型比例 1:2:1，表现型比例 3:1。强调显性掩盖隐性，但因子未消失。可类比抛硬币理解随机结合。",
